kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_addl:		jp 54
kw_subvv:	jp 55
kw_mulvl:	jp 61
kw_divvl:	jp 64
kw_modvl:	jp 67
kw_andvl:	jp 73
kw_orvv:		jp 74
kw_scpltvv:	jp 79
kw_strcpy:	jp 122
kw_strcat:	jp 124
kw_strcmpeq:	jp 126
kw_printzoscii:	jp 129
kw_printstrvar:	jp 130
kw_printint:	jp 132
kw_printnl:	jp 139
